import {
  MeshBasicNodeMaterial,
  DoubleSide,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  AmbientLight,
  SRGBColorSpace
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  texture,
  uniform,
  positionLocal,
  normalLocal
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create primary container
  const container = new Group();

  // Design system constants
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGEBACKDROP (To prevent FLAT_VOID defect, build a backdrop plane carrying a vertical gradient)
  const backdropGeom = new PlaneGeometry(8, 6.5);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide, depthWrite: false });

  const uvNode = uv();
  const gradMix = uvNode.y;
  const bottomColor = vec3(0.043, 0.043, 0.062); // Derived from surface #0b0b10
  const topColor = vec3(0.086, 0.086, 0.114);    // Sightly lighter gradient tone
  backdropMat.colorNode = mix(bottomColor, topColor, gradMix);

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // 2. CONTACT SHADOW (Grounded visual element)
  const shadowGeom = new PlaneGeometry(4.5, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.45,
    depthWrite: false
  });
  // Simple procedural procedural radial shadow falloff
  const shadowUV = uv();
  const distFromCenter = shadowUV.sub(0.5).length();
  const shadowFalloff = mix(1.0, 0.0, distFromCenter.mul(2.2).clamp(0.0, 1.0));
  shadowMat.colorNode = vec4(0.0, 0.0, 0.0, shadowFalloff.mul(0.65));

  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI * 0.45;
  shadow.position.set(0, -1.8, -0.4);
  container.add(shadow);

  // 3. ATELIER BRAND / TEXT HEADER (Using the required fontAtlas system)
  const brandText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.14,
    color: colors.accent,
    align: 'left'
  });
  brandText.position.set(-2.0, 1.2, 0.1);
  container.add(brandText);

  const titleText = ctx.fontAtlas.createText('CHRONO CRAFT // REFINEMENT', {
    fontSize: 0.28,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-2.0, 0.8, 0.1);
  container.add(titleText);

  // 4. MAIN INTERACTIVE DISPLACEMENT PARALLAX CARD
  const cardWidth = 4.2;
  const cardHeight = 2.4;
  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight, 128, 128);
  const cardMaterial = new MeshBasicNodeMaterial({ side: DoubleSide });

  // Set up uniforms for reactive parallax mapping
  const displacementScale = uniform(0.18);
  const uParallaxOffset = uniform(new THREE.Vector2(0, 0));

  // Default color map setup
  let colorTexNode = vec4(0.1, 0.1, 0.12, 1.0);
  let dispTexNode = vec4(0.5, 0.5, 0.5, 1.0);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      cardMaterial.map = tex;
      cardMaterial.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      const depthNodeValue = texture(depthTex, uvNode.add(uParallaxOffset));
      // Displace position local along the normal using scale and depth map value
      const finalPos = positionLocal.add(normalLocal.mul(depthNodeValue.r.mul(displacementScale)));
      cardMaterial.positionNode = finalPos;
      cardMaterial.needsUpdate = true;
    });
  }

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.position.set(0, -0.3, 0);
  container.add(cardMesh);

  // Accent Edge Line (Engineering styling for the active focused state)
  const edgeGeometry = new PlaneGeometry(cardWidth + 0.08, 0.04);
  const edgeMaterial = new MeshBasicNodeMaterial({ color: colors.accent });
  const edgeMesh = new Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.set(0, -0.3 - (cardHeight / 2) - 0.06, 0.02);
  container.add(edgeMesh);

  // 5. LOCAL LIGHTING (Rim illumination directly onto our card)
  const localRimLight = new DirectionalLight(colors.accent, 1.2);
  localRimLight.position.set(3, -2, 4);
  container.add(localRimLight);

  const localFillLight = new AmbientLight(colors.paper, 0.25);
  container.add(localFillLight);

  // 6. MOTION & INTERACTION SPECIFICATION
  const interactiveState = {
    isHovered: false,
    targetY: -0.3,
    targetScale: 1.0,
    parallaxX: 0,
    parallaxY: 0
  };

  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });

  // Motion Handlers attached strictly to userData.handlers
  container.userData.handlers = {
    pointerover: () => {
      interactiveState.isHovered = true;
      gsap.to(cardMesh.position, {
        y: -0.15, // Rise-in subtle 0.15 units
        z: 0.12,
        duration: 0.6,
        overwrite: 'auto'
      });
      gsap.to(edgeMesh.position, {
        y: -0.15 - (cardHeight / 2) - 0.06,
        z: 0.14,
        duration: 0.6,
        overwrite: 'auto'
      });
      gsap.to(edgeMesh.scale, {
        x: 1.05,
        duration: 0.4,
        overwrite: 'auto'
      });
    },

    pointerout: () => {
      interactiveState.isHovered = false;
      gsap.to(cardMesh.position, {
        y: -0.3,
        z: 0.0,
        duration: 0.7,
        ease: 'power4.out',
        overwrite: 'auto'
      });
      gsap.to(edgeMesh.position, {
        y: -0.3 - (cardHeight / 2) - 0.06,
        z: 0.02,
        duration: 0.7,
        ease: 'power4.out',
        overwrite: 'auto'
      });
      gsap.to(edgeMesh.scale, {
        x: 1.0,
        duration: 0.5,
        overwrite: 'auto'
      });
    },

    pointerdown: () => {
      // Press-down response
      gsap.to(cardMesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
    },

    pointerup: () => {
      gsap.to(cardMesh.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.4,
        ease: 'power3.out'
      });

      // Emit events specified in binding
      ctx.emit('hub-features.select', {
        id: config.id,
        imageUrl: config.imageUrl,
        source: 'trpc.checkout.begin.checkoutUrl'
      });
    },

    pointermove: (event) => {
      // Simple normalized mouse/pointer translation logic for parallax mapping
      if (event.intersection) {
        const u = event.intersection.uv.x - 0.5;
        const v = event.intersection.uv.y - 0.5;
        gsap.to(uParallaxOffset.value, {
          x: u * 0.04,
          y: v * 0.04,
          duration: 0.4,
          overwrite: 'auto'
        });
      }
    }
  };

  // 7. CLEANUP
  container.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf([cardMesh.position, cardMesh.scale, edgeMesh.position, edgeMesh.scale, uParallaxOffset.value]);
    backdropGeom.dispose();
    backdropMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    cardGeometry.dispose();
    cardMaterial.dispose();
    edgeGeometry.dispose();
    edgeMaterial.dispose();
  };

  return container;
}
